// What Terragrunt v1.2.2 gave for each call as `x` in a unit's inputs, recorded with `terragrunt render --json` from the
// official release binary terragrunt_darwin_arm64 (sha256 7069eec5127f007525b1178a782e801218342cf223633c6e8508762de19166d6). A
// fault is stated as tghclparser states it: an argument refused as HCL words it, any other failed call as the message
// after `Call to function "<name>" failed: `, and the unit's folder as `<unit>`. The unit's folder held its
// terragrunt.hcl and the files `templateFiles` lists.

/** The files beside the unit's terragrunt.hcl, by path. */
export const templateFiles: Record<string, string> = { 't1.tpl': '${b}', 't2.tpl': 'a\n  é${x}  ${b}', 't3.tpl': '%{ for v in xs }${v}%{ endfor }${c}', 't4.tpl': '%{ if false }${d}%{ endif }${a}', 't5.tpl': '${a.b} ${upper(e)}', 'sub/t6.tpl': '${f}' };

